/// A widget-valued platform argument (a WidgetBuilder), built below [context].
Widget _studioBuild(dynamic builder, BuildContext context) {
  if (builder is Function) {
    final built = builder(context);
    if (built is Widget) return built;
  }
  return const SizedBox.shrink();
}

/// Runs an action-valued platform argument.
void _studioCall(dynamic action, [Map<String, dynamic> event = const {}]) {
  if (action is Function) action(event);
}

/// Like the preview's inline elements: as wide as its content where a column
/// would stretch it, and never asking a row for infinite width.
Widget _studioInline(Widget child, {bool full = false}) => LayoutBuilder(
      builder: (context, constraints) => !constraints.hasBoundedWidth
          ? child
          : full
              ? SizedBox(width: double.infinity, child: child)
              : Row(mainAxisSize: MainAxisSize.min, children: [Flexible(child: child)]),
    );

