/// Button, SubmitButton (submits the form around it) and TriggerButton
/// (opens the drawer around it): primary, secondary or ghost, small when
/// size is a small token, full width when asked.
class StudioButton extends StatelessWidget {
  const StudioButton({super.key, required this.kind, required this.arguments});
  final String kind;
  final Map<String, dynamic> arguments;

  @override
  Widget build(BuildContext context) {
    final label = studioText(arguments['label']);
    final icon = arguments['icon'];
    final size = arguments['size'];
    final small = size is num && size < 20;
    final VoidCallback? onPressed = studioTruthy(arguments['disabled'])
        ? null
        : switch (kind) {
            'SubmitButton' => () => StudioForm.of(context)?.submit(),
            'ResetButton' => () => StudioForm.of(context)?.reset(),
            'TriggerButton' => () => _StudioDrawerScope.of(context)?.call(),
            _ => arguments['onTap'] is Function ? () => _studioCall(arguments['onTap']) : null,
          };
    final given = studioText(arguments['style']);
    final style = given.isNotEmpty ? given : kind == 'TriggerButton' ? 'ghost' : 'primary';
    final shape = ButtonStyle(
      visualDensity: small ? VisualDensity.compact : null,
      padding: small ? const WidgetStatePropertyAll(EdgeInsets.symmetric(horizontal: 10, vertical: 6)) : null,
      minimumSize: small ? const WidgetStatePropertyAll(Size(0, 32)) : null,
      textStyle: small ? WidgetStatePropertyAll(studioFont(fontSize: 12, fontWeight: FontWeight.w600)) : null,
    );
    Widget button;
    if (label.isEmpty && icon is IconData) {
      button = IconButton(onPressed: onPressed, icon: Icon(icon), tooltip: studioText(arguments['ariaLabel']));
    } else {
      final content = icon is IconData
          ? Row(mainAxisSize: MainAxisSize.min, children: [
              Icon(icon, size: small ? 16 : 18),
              const SizedBox(width: 8),
              Flexible(child: Text(label, overflow: TextOverflow.ellipsis)),
            ])
          : Text(label, overflow: TextOverflow.ellipsis);
      button = switch (style) {
        'secondary' => OutlinedButton(onPressed: onPressed, style: shape, child: content),
        'ghost' => TextButton(onPressed: onPressed, style: shape, child: content),
        _ => FilledButton(onPressed: onPressed, style: shape, child: content),
      };
    }
    final aria = studioText(arguments['ariaLabel']);
    if (aria.isNotEmpty) button = Semantics(label: aria, button: true, child: button);
    return _studioInline(button, full: studioTruthy(arguments['fullWidth']));
  }
}

/// Form: the named fields inside it (TextField, SearchField, SelectField)
/// report their values here, and a SubmitButton sends them to onSubmit as
/// the event's values, as PlaceOrder and SavePreviewAddress read them.
class StudioForm extends StatefulWidget {
  const StudioForm({super.key, this.id = '', this.onSubmit, this.onReset, this.builder});
  final String id;
  final dynamic onSubmit, onReset, builder;

  static StudioFormState? of(BuildContext context) =>
      context.getInheritedWidgetOfExactType<_StudioFormScope>()?.form;

  @override
  State<StudioForm> createState() => StudioFormState();
}

/// A field inside a Form: checked when it's submitted (an error stops the
/// submit and shows under the field) and put back when it's reset.
abstract class StudioFormField {
  String? validate();
  void reset();
}

/// Forms by their id, for SubmitForm and ResetForm naming one.
final Map<String, StudioFormState> _studioForms = {};

/// The form an action means: the one it names, or else the one around it.
StudioFormState? studioForm(BuildContext context, String name) =>
    name.isNotEmpty ? _studioForms[name] : StudioForm.of(context);

class StudioFormState extends State<StudioForm> {
  final Map<String, dynamic> values = {};
  final Set<StudioFormField> fields = {};

  @override
  void initState() {
    super.initState();
    if (widget.id.isNotEmpty) _studioForms[widget.id] = this;
  }

  @override
  void dispose() {
    if (_studioForms[widget.id] == this) _studioForms.remove(widget.id);
    super.dispose();
  }

  /// Like the preview: every field is checked, and onSubmit runs only when
  /// none has an error.
  void submit() {
    FocusScope.of(context).unfocus();
    var valid = true;
    for (final field in fields.toList()) {
      if (field.validate() != null) valid = false;
    }
    if (!valid) return;
    _studioCall(widget.onSubmit, {'values': Map<String, dynamic>.of(values)});
  }

  /// Every field back to its first value, its error cleared; then onReset.
  void reset() {
    for (final field in fields.toList()) {
      field.reset();
    }
    _studioCall(widget.onReset, {'values': Map<String, dynamic>.of(values)});
  }

  @override
  Widget build(BuildContext context) =>
      _StudioFormScope(form: this, child: Builder(builder: (context) => _studioBuild(widget.builder, context)));
}

/// The preview's field rules and messages (formRuntime.ts validateField).
String? studioValidate(dynamic value, {required String label, String type = 'text', bool required = false,
    num? min, num? max, int? minLength, int? maxLength}) {
  final empty = value == null || (value is String && value.trim().isEmpty);
  if (required && (empty || value == false)) return label + ' is required.';
  if (empty) return null;
  if (type == 'number' && (value is! num || !value.isFinite)) return 'Enter a number for ' + label + '.';
  if (value is num) {
    if (min != null && value < min) return label + ' must be at least ' + _studioNumText(min) + '.';
    if (max != null && value > max) return label + ' must be at most ' + _studioNumText(max) + '.';
  }
  if (value is String) {
    if (minLength != null && value.length < minLength) {
      return label + ' needs at least ' + minLength.toString() + ' characters.';
    }
    if (maxLength != null && value.length > maxLength) {
      return label + ' allows at most ' + maxLength.toString() + ' characters.';
    }
    if (type == 'email' && !RegExp(r'^[^\s@]+@[^\s@]+\.[^\s@]+$').hasMatch(value)) {
      return 'Enter a valid email address.';
    }
    if (type == 'url') {
      final uri = Uri.tryParse(value);
      if (uri == null || !uri.hasScheme) return 'Enter a valid URL.';
      if (uri.scheme != 'http' && uri.scheme != 'https') return 'Enter an HTTP(S) URL.';
    }
  }
  return null;
}

/// A number as the preview writes it: 5, not 5.0.
String _studioNumText(num value) => value == value.roundToDouble() ? value.toInt().toString() : value.toString();

class _StudioFormScope extends InheritedWidget {
  const _StudioFormScope({required this.form, required super.child});
  final StudioFormState form;
  @override
  bool updateShouldNotify(_StudioFormScope oldWidget) => false;
}

/// SelectField: a labelled dropdown of its SelectOptions, reporting its value
/// to the form around it under its name.
class StudioSelectField extends StatefulWidget {
  const StudioSelectField({super.key, required this.arguments});
  final Map<String, dynamic> arguments;
  @override
  State<StudioSelectField> createState() => _StudioSelectFieldState();
}

class _StudioSelectFieldState extends State<StudioSelectField> implements StudioFormField {
  String? value;
  /// What it started with, for a reset.
  String? initial;
  StudioFormState? form;
  String? error;

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final around = StudioForm.of(context);
    if (around != form) {
      form?.fields.remove(this);
      form = around;
      around?.fields.add(this);
    }
  }

  @override
  void dispose() {
    form?.fields.remove(this);
    super.dispose();
  }

  @override
  String? validate() {
    final label = studioText(widget.arguments['label']).isNotEmpty
        ? studioText(widget.arguments['label'])
        : studioText(widget.arguments['name'] ?? widget.arguments['state']).isNotEmpty
            ? studioText(widget.arguments['name'] ?? widget.arguments['state'])
            : 'This field';
    final message = studioTruthy(widget.arguments['disabled'])
        ? null
        : studioValidate(value, label: label, required: studioTruthy(widget.arguments['required']));
    if (message != error) setState(() => error = message);
    return message;
  }

  @override
  void reset() => setState(() {
        value = initial;
        error = null;
        report();
      });

  List<Map<String, dynamic>> options(BuildContext context) {
    final built = widget.arguments['options'] is Function ? widget.arguments['options'](context) : null;
    return [
      if (built is List)
        for (final option in built.whereType<StudioPlatformWidget>()) option.arguments,
    ];
  }

  void report() {
    final name = studioText(widget.arguments['name'] ?? widget.arguments['state']);
    if (name.isNotEmpty && value != null) StudioForm.of(context)?.values[name] = value;
  }

  @override
  Widget build(BuildContext context) {
    final choices = options(context);
    final values = [for (final option in choices) studioText(option['value'])];
    value ??= values.contains(studioText(widget.arguments['value']))
        ? studioText(widget.arguments['value'])
        : (values.isEmpty ? null : values.first);
    initial ??= value;
    report();
    final border = widget.arguments['border'];
    final radius = studioNumber(widget.arguments['radius'] ?? 9);
    final label = studioText(widget.arguments['label']);
    final field = Container(
      padding: const EdgeInsets.symmetric(horizontal: 12),
      decoration: BoxDecoration(
        color: widget.arguments['background'] is Color
            ? widget.arguments['background'] as Color
            : studioColor(context, 'surface'),
        borderRadius: BorderRadius.circular(radius),
        border: border is BoxBorder ? border : Border.all(color: studioColor(context, 'border')),
      ),
      child: DropdownButton<String>(
        value: value,
        isExpanded: true,
        underline: const SizedBox.shrink(),
        style: studioFont(fontSize: 13, color: studioColor(context, 'text')),
        items: [
          for (final option in choices)
            DropdownMenuItem(value: studioText(option['value']), child: Text(studioText(option['label']))),
        ],
        onChanged: studioTruthy(widget.arguments['disabled'])
            ? null
            : (next) => setState(() {
                  value = next;
                  report();
                  if (error != null) validate();
                }),
      ),
    );
    final labelled = label.isEmpty && error == null
        ? field
        : Column(crossAxisAlignment: CrossAxisAlignment.stretch, mainAxisSize: MainAxisSize.min, children: [
            if (label.isNotEmpty)
              Text(label, style: studioFont(fontSize: 13, fontWeight: FontWeight.w500, color: studioColor(context, 'text'))),
            if (label.isNotEmpty) const SizedBox(height: 6),
            field,
            if (error != null) const SizedBox(height: 6),
            if (error != null) Text(error!, style: studioFont(fontSize: 11, color: studioColor(context, 'danger'))),
          ]);
    return LayoutBuilder(
      builder: (context, constraints) =>
          constraints.hasBoundedWidth ? labelled : SizedBox(width: 240, child: labelled),
    );
  }
}

/// Drawer: its trigger (a TriggerButton) slides its child in from the side.
/// Navigating from inside closes it (see studioNavigate).
/// Opened from its trigger, or (open given) while open is true: onClose runs
/// when the person closes it, so the page can set open back. Side.bottom is
/// a sheet up from the bottom; left and right slide in from that side.
class StudioDrawer extends StatefulWidget {
  const StudioDrawer({super.key, this.side = 'left', this.trigger, this.builder, this.open, this.onClose});
  final String side;
  final dynamic trigger, builder, onClose;
  /// Shown while true; null: only its trigger opens it.
  final bool? open;

  @override
  State<StudioDrawer> createState() => _StudioDrawerState();
}

class _StudioDrawerState extends State<StudioDrawer> {
  /// The panel while it's showing, to close it when open turns false.
  Route<void>? _shown;
  /// Closed by the page (open turned false), not by the person: onClose isn't run.
  bool _closing = false;

  bool get _bottom => widget.side.endsWith('bottom');

  Route<void> _route(BuildContext context) {
    Widget contents(BuildContext context) => Builder(builder: (context) => _studioBuild(widget.builder, context));
    if (_bottom) {
      return ModalBottomSheetRoute<void>(
        isScrollControlled: true,
        showDragHandle: true,
        useSafeArea: true,
        backgroundColor: studioColor(context, 'surface'),
        builder: (sheetContext) => Padding(
          // Above the keyboard, for a sign-in form.
          padding: EdgeInsets.only(bottom: MediaQuery.viewInsetsOf(sheetContext).bottom),
          child: SingleChildScrollView(child: contents(sheetContext)),
        ),
      );
    }
    final right = widget.side.endsWith('right');
    return RawDialogRoute<void>(
      barrierDismissible: true,
      barrierLabel: 'Close menu',
      barrierColor: Colors.black54,
      transitionDuration: const Duration(milliseconds: 220),
      pageBuilder: (dialogContext, animation, secondary) => Align(
        alignment: right ? Alignment.centerRight : Alignment.centerLeft,
        child: Material(
          color: studioColor(dialogContext, 'surface'),
          child: SafeArea(
            child: SizedBox(
              width: math.min(320, MediaQuery.sizeOf(dialogContext).width * 0.85),
              height: double.infinity,
              child: SingleChildScrollView(child: contents(dialogContext)),
            ),
          ),
        ),
      ),
      transitionBuilder: (context, animation, secondary, child) => SlideTransition(
        position: Tween(begin: Offset(right ? 1 : -1, 0), end: Offset.zero)
            .animate(CurvedAnimation(parent: animation, curve: Curves.easeOut)),
        child: child,
      ),
    );
  }

  void _show() {
    if (_shown != null || !mounted) return;
    final route = _route(context);
    _shown = route;
    Navigator.of(context).push(route).whenComplete(() {
      if (_shown != route) return;
      _shown = null;
      if (_closing) {
        _closing = false;
      } else {
        // The person closed it: tell the page.
        final onClose = widget.onClose;
        if (onClose is Function) onClose(<String, dynamic>{});
      }
    });
  }

  void _hide() {
    final route = _shown;
    if (route == null || !route.isActive) return;
    _closing = true;
    route.navigator?.removeRoute(route);
  }

  void _follow() {
    final open = widget.open;
    if (open == null) return;
    // After this frame: a route can't be pushed or removed while building.
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      if (open && _shown == null) _show();
      if (!open && _shown != null) _hide();
    });
  }

  @override
  void initState() {
    super.initState();
    _follow();
  }

  @override
  void didUpdateWidget(StudioDrawer old) {
    super.didUpdateWidget(old);
    if (old.open != widget.open) _follow();
  }

  @override
  void dispose() {
    // Its panel goes with it, once the Navigator isn't mid-change.
    final route = _shown;
    _shown = null;
    if (route != null) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (route.isActive) route.navigator?.removeRoute(route);
      });
    }
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => _StudioDrawerScope(
        open: _show,
        child: widget.trigger == null ? const SizedBox.shrink() : Builder(builder: (context) => _studioBuild(widget.trigger, context)),
      );
}

class _StudioDrawerScope extends InheritedWidget {
  const _StudioDrawerScope({required this.open, required super.child});
  final VoidCallback open;
  static VoidCallback? of(BuildContext context) =>
      context.getInheritedWidgetOfExactType<_StudioDrawerScope>()?.open;
  @override
  bool updateShouldNotify(_StudioDrawerScope oldWidget) => false;
}

