/// Carousel: its items side by side at itemWidth, scrolled sideways; it can
/// settle on an item (snap), page with arrows and show where it is (dots).
class StudioCarousel extends StatefulWidget {
  const StudioCarousel({super.key, this.items, this.itemWidth = 0, this.gap = 0,
      this.showDots = false, this.showArrows = false, this.snap = true});
  final dynamic items;
  final double itemWidth, gap;
  final bool showDots, showArrows, snap;

  @override
  State<StudioCarousel> createState() => _StudioCarouselState();
}

class _StudioCarouselState extends State<StudioCarousel> {
  final controller = ScrollController();
  int index = 0;

  double get width => widget.itemWidth > 0 ? widget.itemWidth : 220;
  double get step => width + widget.gap;

  @override
  void initState() {
    super.initState();
    controller.addListener(() {
      final at = (controller.offset / step).round();
      if (at != index) setState(() => index = at);
    });
  }

  @override
  void dispose() {
    controller.dispose();
    super.dispose();
  }

  void go(int to, int count) {
    if (!controller.hasClients || count == 0) return;
    final target = (to.clamp(0, count - 1) * step).clamp(0.0, controller.position.maxScrollExtent);
    controller.animateTo(target, duration: const Duration(milliseconds: 300), curve: Curves.easeOut);
  }

  @override
  Widget build(BuildContext context) {
    final built = widget.items is Function ? widget.items(context) : null;
    final items = built is List ? built.whereType<Widget>().toList() : <Widget>[];
    Widget strip = SingleChildScrollView(
      controller: controller,
      scrollDirection: Axis.horizontal,
      child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
        for (var i = 0; i < items.length; i++) ...[
          if (i > 0) SizedBox(width: widget.gap),
          SizedBox(width: width, child: items[i]),
        ],
      ]),
    );
    if (widget.snap) {
      // Settles on the nearest item once a swipe ends.
      strip = NotificationListener<ScrollEndNotification>(
        onNotification: (_) {
          if (!controller.hasClients) return false;
          final target = ((controller.offset / step).round() * step).clamp(0.0, controller.position.maxScrollExtent);
          if ((target - controller.offset).abs() > 1) {
            Future.microtask(() => controller.animateTo(target, duration: const Duration(milliseconds: 200), curve: Curves.easeOut));
          }
          return false;
        },
        child: strip,
      );
    }
    if (widget.showArrows && items.length > 1) {
      Widget arrow(IconData icon, String label, int to, bool enabled) => IconButton.filledTonal(
            onPressed: enabled ? () => go(to, items.length) : null,
            tooltip: label,
            icon: Icon(icon, size: 18),
          );
      strip = Stack(alignment: Alignment.center, children: [
        strip,
        Positioned(left: 4, child: arrow(Icons.chevron_left, 'Previous', index - 1, index > 0)),
        Positioned(right: 4, child: arrow(Icons.chevron_right, 'Next', index + 1, index < items.length - 1)),
      ]);
    }
    if (!widget.showDots || items.length < 2) return strip;
    return Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      strip,
      const SizedBox(height: 10),
      Row(mainAxisAlignment: MainAxisAlignment.center, children: [
        for (var i = 0; i < items.length; i++)
          GestureDetector(
            onTap: () => go(i, items.length),
            child: Container(
              width: i == index ? 16 : 6,
              height: 6,
              margin: const EdgeInsets.symmetric(horizontal: 3),
              decoration: BoxDecoration(
                color: studioColor(context, i == index ? 'primary' : 'border'),
                borderRadius: BorderRadius.circular(3),
              ),
            ),
          ),
      ]),
    ]);
  }
}

/// Tabs: a bar of its Tabs' labels (underline, pill or segmented) and the
/// chosen one's content below it.
class StudioTabs extends StatefulWidget {
  const StudioTabs({super.key, this.tabs, this.initial = 0, this.style = ''});
  final dynamic tabs;
  final int initial;
  final String style;

  @override
  State<StudioTabs> createState() => _StudioTabsState();
}

class _StudioTabsState extends State<StudioTabs> {
  late int selected = widget.initial;

  @override
  Widget build(BuildContext context) {
    final built = widget.tabs is Function ? widget.tabs(context) : null;
    final tabs = [
      if (built is List)
        for (final tab in built.whereType<StudioPlatformWidget>()) tab.arguments,
    ];
    if (tabs.isEmpty) return const SizedBox.shrink();
    final at = selected.clamp(0, tabs.length - 1);
    final style = widget.style.isEmpty ? 'underline' : widget.style;
    Widget tab(int i) {
      final on = i == at;
      final label = Text(
        studioText(tabs[i]['label']),
        style: studioFont(
          fontSize: 13,
          fontWeight: on ? FontWeight.w600 : FontWeight.w500,
          color: on
              ? studioColor(context, style == 'pill' ? 'primaryInk' : 'text')
              : studioColor(context, 'textMuted'),
        ),
      );
      final decoration = switch (style) {
        'pill' => BoxDecoration(
            color: on ? studioColor(context, 'primary') : null, borderRadius: BorderRadius.circular(999)),
        'segmented' => BoxDecoration(
            color: on ? studioColor(context, 'surface') : null,
            borderRadius: BorderRadius.circular(8),
            boxShadow: on ? studioBoxShadow('sm') : null),
        _ => BoxDecoration(
            border: Border(bottom: BorderSide(color: on ? studioColor(context, 'primary') : Colors.transparent, width: 2))),
      };
      return Semantics(
        selected: on,
        button: true,
        child: InkWell(
          onTap: () => setState(() => selected = i),
          borderRadius: BorderRadius.circular(style == 'underline' ? 0 : 999),
          child: Container(
            padding: EdgeInsets.symmetric(horizontal: style == 'underline' ? 12 : 14, vertical: 8),
            decoration: decoration,
            child: label,
          ),
        ),
      );
    }

    final row = Row(mainAxisSize: MainAxisSize.min, children: [for (var i = 0; i < tabs.length; i++) tab(i)]);
    final bar = switch (style) {
      'segmented' => Container(
          padding: const EdgeInsets.all(3),
          decoration: BoxDecoration(color: studioColor(context, 'surfaceAlt'), borderRadius: BorderRadius.circular(10)),
          child: row),
      'underline' => Container(
          decoration: BoxDecoration(border: Border(bottom: BorderSide(color: studioColor(context, 'border')))),
          child: row),
      _ => row,
    };
    return Column(crossAxisAlignment: CrossAxisAlignment.stretch, mainAxisSize: MainAxisSize.min, children: [
      SingleChildScrollView(scrollDirection: Axis.horizontal, child: bar),
      const SizedBox(height: 12),
      Builder(builder: (context) => _studioBuild(tabs[at]['child'], context)),
    ]);
  }
}

/// Checkbox: a labelled tick box reporting to its form (and its state) under
/// its name; required means it has to be ticked.
class StudioCheckbox extends StatefulWidget {
  const StudioCheckbox({super.key, this.value, this.controlled = false, this.label = '', this.name = '',
      this.helper, this.enabled = true, this.required = false, this.onChanged});
  final dynamic value;
  final bool controlled, enabled, required;
  final String label, name;
  final String? helper;
  final StudioAction? onChanged;

  @override
  State<StudioCheckbox> createState() => _StudioCheckboxState();
}

class _StudioCheckboxState extends State<StudioCheckbox> implements StudioFormField {
  late bool checked = studioTruthy(widget.value);
  late final bool initial = checked;
  StudioFormState? form;
  String? error;

  Map<String, dynamic> event(bool value) => {'input': {'value': value, 'checked': value, 'name': widget.name}};

  void report() {
    if (widget.name.isNotEmpty) form?.values[widget.name] = checked;
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final around = StudioForm.of(context);
    if (around != form) {
      form?.fields.remove(this);
      form = around;
      around?.fields.add(this);
    }
    report();
  }

  @override
  void didUpdateWidget(covariant StudioCheckbox oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.controlled && studioTruthy(widget.value) != checked) checked = studioTruthy(widget.value);
  }

  @override
  void dispose() {
    form?.fields.remove(this);
    super.dispose();
  }

  @override
  String? validate() {
    final label = widget.label.isNotEmpty ? widget.label : widget.name.isNotEmpty ? widget.name : 'This field';
    final message = widget.enabled ? studioValidate(checked, label: label, required: widget.required) : null;
    if (message != error) setState(() => error = message);
    return message;
  }

  @override
  void reset() => setState(() {
        checked = initial;
        error = null;
        report();
      });

  void change(bool value) {
    setState(() => checked = value);
    report();
    if (error != null) validate();
    widget.onChanged?.call(event(value));
  }

  @override
  Widget build(BuildContext context) {
    final box = Row(mainAxisSize: MainAxisSize.min, children: [
      Checkbox(value: checked, onChanged: widget.enabled ? (value) => change(value ?? false) : null),
      Flexible(
        child: Text(widget.label, style: studioFont(fontSize: 13, color: studioColor(context, 'text'))),
      ),
    ]);
    return Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisSize: MainAxisSize.min, children: [
      Semantics(
        checked: checked,
        label: widget.label,
        child: InkWell(onTap: widget.enabled ? () => change(!checked) : null, child: box),
      ),
      if (widget.helper != null && widget.helper!.isNotEmpty)
        Padding(
          padding: const EdgeInsets.only(left: 12),
          child: Text(widget.helper!, style: studioFont(fontSize: 11, color: studioColor(context, 'textMuted'))),
        ),
      if (error != null)
        Padding(
          padding: const EdgeInsets.only(left: 12, top: 4),
          child: Text(error!, style: studioFont(fontSize: 11, color: studioColor(context, 'danger'))),
        ),
    ]);
  }
}

/// A Box's id, as a place ScrollTo can bring into view.
final Map<String, GlobalKey> _studioAnchors = {};

class StudioAnchor extends StatefulWidget {
  const StudioAnchor({super.key, required this.id, required this.child});
  final String id;
  final Widget child;

  @override
  State<StudioAnchor> createState() => _StudioAnchorState();
}

class _StudioAnchorState extends State<StudioAnchor> {
  final key = GlobalKey();

  @override
  void initState() {
    super.initState();
    if (widget.id.isNotEmpty) _studioAnchors[widget.id] = key;
  }

  @override
  void didUpdateWidget(covariant StudioAnchor oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.id != widget.id) {
      if (_studioAnchors[oldWidget.id] == key) _studioAnchors.remove(oldWidget.id);
      if (widget.id.isNotEmpty) _studioAnchors[widget.id] = key;
    }
  }

  @override
  void dispose() {
    if (_studioAnchors[widget.id] == key) _studioAnchors.remove(widget.id);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => KeyedSubtree(key: key, child: widget.child);
}

/// ScrollTo: brings the Box with this id into view, wherever it scrolls.
void studioScrollTo(String id) {
  final target = _studioAnchors[id]?.currentContext;
  if (target != null) {
    Scrollable.ensureVisible(target, duration: const Duration(milliseconds: 350), curve: Curves.easeOut, alignment: 0.1);
  }
}

/// A record's id, or the value itself when a page passes the id.
String _studioId(dynamic value, String key) => value is Map ? studioText(value[key]) : studioText(value);

/// The location is set: the stores near it load, and the store page opens.
void _studioFindStores(BuildContext context, Storefront storefront) {
  if (storefront.connected) storefront.searchStores().then((_) {}, onError: (Object _) {});
  studioNavigate(context, studioRoute('stores'));
}

/// Opens a store's menu at once, as _studioFindStores opens the store list:
/// the menu page shows its loading outline while the menu arrives, instead
/// of the tap waiting on the network (the request runs off the UI thread
/// either way). Until then the tapped store's card stands in for the store,
/// so its name shows, and another store's menu is set aside so it can't
/// show meanwhile. A failure is said where the customer now is.
void _studioOpenStore(BuildContext context, Storefront storefront, dynamic store) {
  final id = _studioId(store, 'id');
  if (storefront.connected && id.isNotEmpty) {
    final current = storefront.store;
    if (current == null || (current.id != id && current.slug != id)) {
      storefront.menu = null;
      storefront.cuisines = null;
      storefront.deliveryOptions = null;
      try {
        storefront.store = store is Map ? Store.fromJson(Map<String, dynamic>.from(store)) : null;
      } on FormatException {
        storefront.store = null;
      }
    }
    final messenger = ScaffoldMessenger.maybeOf(context);
    storefront.selectStore(id).then((_) {}, onError: (Object failure) {
      messenger
        ?..hideCurrentSnackBar()
        ..showSnackBar(studioSnackBar(context, studioErrorText(failure)));
    });
  }
  studioNavigate(context, studioRoute('menu'));
}

/// The letters of a name, for an Image whose fallback is initials.
Widget _studioInitials(BuildContext context, String name) {
  final letters = name.trim().split(RegExp(r'\s+')).take(2).map((word) => word[0].toUpperCase()).join();
  return ColoredBox(
    color: Theme.of(context).colorScheme.surfaceContainerHighest,
    child: Center(child: Text(letters, style: TextStyle(fontWeight: FontWeight.w700, color: studioColor(context, 'textMuted')))),
  );
}

/// A network picture, as tiptap-frontend draws its catalogue: decoded no
/// larger than it is drawn, shimmering while the bytes arrive, faded in once
/// they do, and a quiet placeholder when there is no URL or it fails.
///
/// Decode size matters most in a list. A product photo of ~500px drawn at
/// 64px decodes to many times the bitmap it needs, and a menu of them
/// overflows Flutter's image cache, so scrolling back re-decodes what it
/// evicted. Capping the decode at the drawn size (one side only, so the
/// picture keeps its shape for BoxFit.cover to crop) keeps a long menu in
/// memory.
class StudioNetworkImage extends StatelessWidget {
  const StudioNetworkImage({super.key, required this.src, this.fit = BoxFit.cover, this.semanticLabel, this.fallback, this.icon = Icons.image_outlined});
  final dynamic src;
  final BoxFit fit;
  final String? semanticLabel;
  /// Drawn instead of the placeholder when there is no picture or it fails.
  final Widget? fallback;
  final IconData icon;

  @override
  Widget build(BuildContext context) {
    final src = this.src;
    final failed = fallback ??
        ColoredBox(
          color: Theme.of(context).colorScheme.surfaceContainerHighest,
          child: Center(child: Icon(icon, color: studioColor(context, 'textMuted'))),
        );
    if (src is! String || !(src.startsWith('http://') || src.startsWith('https://'))) return failed;
    return LayoutBuilder(builder: (context, constraints) {
      final ratio = MediaQuery.maybeDevicePixelRatioOf(context) ?? 1.0;
      bool usable(double side) => side.isFinite && side > 0;
      // A height only when the frame sets one (an AspectRatio, a SizedBox):
      // a column's room is not the picture's size.
      final w = constraints.maxWidth, h = constraints.hasTightHeight ? constraints.maxHeight : double.infinity;
      // The longer side: cover crops from whichever axis overflows.
      final cacheWidth = usable(w) && (!usable(h) || w >= h) ? (w * ratio).round() : null;
      final cacheHeight = cacheWidth == null && usable(h) ? (h * ratio).round() : null;
      return Image(
        image: ResizeImage.resizeIfNeeded(cacheWidth, cacheHeight, NetworkImage(src)),
        fit: fit,
        width: usable(w) ? w : null,
        height: usable(h) ? h : null,
        semanticLabel: semanticLabel,
        excludeFromSemantics: semanticLabel == null,
        gaplessPlayback: true,
        frameBuilder: (context, child, frame, synchronous) => synchronous
            ? child
            : AnimatedOpacity(
                opacity: frame == null ? 0 : 1,
                duration: const Duration(milliseconds: 220),
                curve: Curves.easeOut,
                child: child,
              ),
        loadingBuilder: (context, child, progress) => progress == null
            ? child
            : Stack(fit: StackFit.passthrough, children: [const Positioned.fill(child: StudioSkeleton(radius: 0)), child]),
        errorBuilder: (context, error, stack) => failed,
      );
    });
  }
}

/// Whether the storefront is fetching what a list shows: 'stores', the
/// chosen store's 'menu' (products, categories, cuisines) or the customer's
/// 'orders'. Never while unconnected, on sample data, or when the app brings
/// its own platform.
bool studioLoading(BuildContext context, Map<String, dynamic> bindings, String source) {
  if (bindings['_studio'] is StudioPlatform) return false;
  final storefront = context.dependOnInheritedWidgetOfExactType<StudioStorefrontScope>()?.notifier;
  if (storefront == null || !storefront.connected) return false;
  // A page fetching its own data (its Data settings) is loading it until it's in.
  final page = context.dependOnInheritedWidgetOfExactType<StudioPageDataScope>();
  if (page != null && page.loading && source != 'orders') return true;
  final status = switch (source) {
    'stores' => storefront.storesStatus,
    'orders' => storefront.ordersStatus,
    _ => storefront.menuStatus,
  };
  return status == StorefrontStatus.loading;
}

const _studioSweep = Duration(milliseconds: 1500);

/// A block the shape of what is loading, with a light sweeping across it in
/// the brand's tint. Keyed to the clock rather than to when it was built, so
/// a screenful shimmers as one surface; still when animations are off.
class StudioSkeleton extends StatefulWidget {
  const StudioSkeleton({super.key, this.width, this.height, this.radius = 8});
  /// Null fills what it's given.
  final double? width, height;
  final double radius;
  @override
  State<StudioSkeleton> createState() => _StudioSkeletonState();
}

class _StudioSkeletonState extends State<StudioSkeleton> with SingleTickerProviderStateMixin {
  late final AnimationController _controller = AnimationController(vsync: this, duration: _studioSweep);

  @override
  void initState() {
    super.initState();
    final period = _studioSweep.inMilliseconds;
    _controller.value = (DateTime.now().millisecondsSinceEpoch % period) / period;
    _controller.repeat();
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final colors = Theme.of(context).colorScheme;
    final dark = Theme.of(context).brightness == Brightness.dark;
    final base = Color.alphaBlend(colors.primary.withValues(alpha: dark ? 0.10 : 0.07), colors.surfaceContainerHighest);
    final light = Color.alphaBlend(Colors.white.withValues(alpha: dark ? 0.07 : 0.6), base);
    final radius = BorderRadius.circular(widget.radius);
    if (MediaQuery.maybeDisableAnimationsOf(context) ?? false) {
      return Container(width: widget.width, height: widget.height, decoration: BoxDecoration(color: base, borderRadius: radius));
    }
    return AnimatedBuilder(
      animation: _controller,
      builder: (context, _) {
        // The band travels from well off the left edge to well off the right.
        final t = _controller.value * 3 - 1;
        return Container(
          width: widget.width,
          height: widget.height,
          decoration: BoxDecoration(
            borderRadius: radius,
            gradient: LinearGradient(
              begin: Alignment(t - 1, -0.3),
              end: Alignment(t + 1, 0.3),
              colors: [base, light, base],
              stops: const [0.35, 0.5, 0.65],
            ),
          ),
        );
      },
    );
  }
}

/// One generated outline of a list item: read out as loading, not tappable.
class StudioSkeletonGroup extends StatelessWidget {
  const StudioSkeletonGroup({super.key, required this.child});
  final Widget child;
  @override
  Widget build(BuildContext context) => Semantics(
        label: 'Loading',
        child: ExcludeSemantics(child: IgnorePointer(child: child)),
      );
}

/// A line of text on its way: a bar the height of the text, about as wide
/// as the text is likely to be.
class StudioSkeletonText extends StatelessWidget {
  const StudioSkeletonText({super.key, this.size, this.widthFactor = 0.6, this.lines = 1, this.align = TextAlign.start});
  final double? size;
  final double widthFactor;
  final int lines;
  final TextAlign align;
  @override
  Widget build(BuildContext context) {
    final size = this.size ?? DefaultTextStyle.of(context).style.fontSize ?? 14;
    final alignment = switch (align) {
      TextAlign.center => Alignment.center,
      TextAlign.end || TextAlign.right => AlignmentDirectional.centerEnd,
      _ => AlignmentDirectional.centerStart,
    };
    return LayoutBuilder(builder: (context, constraints) {
      final room = constraints.hasBoundedWidth ? constraints.maxWidth : size * 10;
      return Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          for (var line = 0; line < lines; line++)
            Padding(
              padding: EdgeInsets.symmetric(vertical: size * 0.2),
              child: Align(
                alignment: alignment,
                heightFactor: 1,
                child: StudioSkeleton(
                  height: size,
                  width: room * (line == lines - 1 && lines > 1 ? widthFactor * 0.6 : widthFactor),
                  radius: size / 3,
                ),
              ),
            ),
        ],
      );
    });
  }
}

/// A picture, button or field on its way. Without a width it fills the
/// room it has (a button's width where the room is unbounded).
class StudioSkeletonBlock extends StatelessWidget {
  const StudioSkeletonBlock({super.key, this.width, this.height, this.aspectRatio, this.radius = 8});
  final double? width, height, aspectRatio;
  final double radius;
  @override
  Widget build(BuildContext context) => LayoutBuilder(builder: (context, constraints) {
        final width = this.width ?? (constraints.hasBoundedWidth ? constraints.maxWidth : 96.0);
        final ratio = aspectRatio;
        final height = this.height ?? (ratio != null && ratio > 0 ? width / ratio : 48.0);
        return StudioSkeleton(width: width, height: height, radius: radius);
      });
}

class StudioPlatformWidget extends StatelessWidget {
  const StudioPlatformWidget({super.key, required this.name, required this.arguments, required this.bindings});
  final String name;
  final Map<String, dynamic> arguments, bindings;
  @override
  Widget build(BuildContext context) => studioPlatform(bindings).buildWidget(context, name, arguments, studioAmbient(context, bindings));
}
/// Widget-valued integration arguments are lazy WidgetBuilder callbacks. List-valued
/// arguments are BuildContext -> List<Widget>. Invoke them below the integration's scope.
class StudioScope extends InheritedWidget {
  const StudioScope({super.key, required this.values, required super.child});
  final Map<String, dynamic> values;
  @override
  bool updateShouldNotify(StudioScope oldWidget) => true;
}
Map<String, dynamic> studioAmbient(BuildContext context, Map<String, dynamic> bindings, {bool imports = true}) {
  final values = {...bindings, ...?context.dependOnInheritedWidgetOfExactType<StudioScope>()?.values};
  // What the page's Data settings imported, by name: over any built-in.
  // Without them (imports: false) for studioClient: a page's Client import
  // named cart or stores must not hide the cart or the stores it reads.
  final imported = imports ? studioImported(context.dependOnInheritedWidgetOfExactType<StudioPageDataScope>()?.data) : null;
  // The storefront (package:upskale_storefront) answers for the store, menu,
  // cart and the open product's options, unless the app brings its own platform.
  final storefront = context.dependOnInheritedWidgetOfExactType<StudioStorefrontScope>()?.notifier;
  if (storefront == null || values['_studio'] is StudioPlatform) return {...values, ...?imported};
  final auth = _StudioAuth.of(storefront);
  _studioLoadOrders(storefront);
  return {
    ...values,
    ..._StudioBindingsCache.of(storefront).bindings(imported?['product'] ?? values['product']),
    'signedIn': storefront.session?.signedIn ?? false,
    'signingIn': auth.working,
    'authError': auth.error,
    ...?imported,
  };
}

/// What a page or component imports from the client (Client.cart(), …): the
/// storefront's own state, reshaped as Studio's CLIENT_RESOURCES name it
/// (clientData.ts in Studio). Read on every build, so it follows the cart.
dynamic studioClient(BuildContext context, Map<String, dynamic> bindings, String resource) {
  final state = studioAmbient(context, bindings, imports: false);
  List<dynamic> list(String key) => state[key] is List ? state[key] as List : const [];
  switch (resource) {
    case 'cart':
      final lines = list('cart');
      var count = 0, total = 0;
      for (final line in lines) {
        if (line is! Map) continue;
        count += (line['quantity'] as num?)?.toInt() ?? 0;
        total += (line['line_total_cents'] as num?)?.toInt() ?? 0;
      }
      return {'lines': lines, 'count': count, 'total_cents': state['cartTotal'] is num ? state['cartTotal'] : total};
    case 'store':
      return state['store'];
    case 'stores':
      return {'results': list('stores'), 'loading': state['storesLoading'] == true};
    case 'location':
      final where = state['location'] is Map ? state['location'] as Map : null;
      return {
        'set': where != null,
        'label': where?['label'] ?? '',
        'latitude': where?['latitude'],
        'longitude': where?['longitude'],
        'locating': state['locating'] == true,
        'error': state['locationError'],
        'places': list('places'),
        'cities': list('cities'),
      };
    case 'checkout':
      // A page showing the checkout: its quote (charges, fees, the total) kept current.
      _studioKeepQuote(context);
      return {
        if (state['checkout'] is Map) ...Map<String, dynamic>.from(state['checkout'] as Map),
        'quote': state['quote'],
      };
    case 'session':
      return {'signed_in': state['signedIn'] == true, 'signing_in': state['signingIn'] == true, 'error': state['authError']};
    case 'choices':
      return {
        if (state['configuration'] is Map) ...Map<String, dynamic>.from(state['configuration'] as Map),
        'groups': list('optionGroups'),
      };
    case 'review':
      return state['review'];
  }
  return null;
}

/// The customer's session token, kept securely on the device: the Keychain
/// on iOS and macOS, encrypted storage (the Keystore's key) on Android, and
/// the browser's own storage on the web. So a customer stays signed in, and
/// keeps their orders, across app starts; main.dart hands it to
/// Storefront.configure. A store the device can't read is no session.
class StudioTokenStore implements StorefrontTokenStore {
  const StudioTokenStore();
  static const _storage = FlutterSecureStorage();
  static const _key = 'upskale.session';

  @override
  Future<String?> read() async {
    try {
      return await _storage.read(key: _key);
    } catch (_) {
      return null;
    }
  }

  @override
  Future<void> write(String? token) async {
    try {
      if (token == null) {
        await _storage.delete(key: _key);
      } else {
        await _storage.write(key: _key, value: token);
      }
    } catch (_) {
      // Kept for this start only.
    }
  }
}

final _studioOrdersAsked = Expando<bool>();

/// The customer's orders, loaded from the API once an app is connected
/// (they're theirs, from earlier starts too), not only those placed since it
/// opened: once per storefront, again after signing in.
void _studioLoadOrders(Storefront storefront) {
  // Asked on every read of the bindings: scheduled once.
  if (_studioOrdersAsked[storefront] == true) return;
  if (!storefront.connected || storefront.ordersStatus != StorefrontStatus.idle) return;
  _studioOrdersAsked[storefront] = true;
  WidgetsBinding.instance.addPostFrameCallback((_) {
    if (storefront.ordersStatus == StorefrontStatus.idle) storefront.loadOrders().ignore();
  });
}

/// SignIn and SignUp's progress, by storefront: working while one runs
/// (signingIn), and why the last one didn't (authError). Changing it
/// rebuilds what reads the storefront.
class _StudioAuth {
  static final _states = Expando<_StudioAuth>();
  static _StudioAuth of(Storefront storefront) => _states[storefront] ??= _StudioAuth();
  bool working = false;
  String? error;

  void set(Storefront storefront, bool working, String? error) {
    if (this.working == working && this.error == error) return;
    this.working = working;
    this.error = error;
    // The storefront is what pages listen to; this is its state too.
    // ignore: invalid_use_of_protected_member, invalid_use_of_visible_for_testing_member
    storefront.notifyListeners();
  }
}

/// Opens where to pay for an online order, in the browser (the business's
/// provider, PayFast). The tracking page hears the order move on once paid.
void _studioPayOnline(Storefront storefront, String orderId, void Function(String) notice) {
  storefront.payOnline(orderId).then((url) async {
    if (!await launchUrl(url, mode: LaunchMode.externalApplication)) {
      notice("Couldn't open the payment page. Try again.");
    }
  }, onError: (Object failure) => notice(studioErrorText(failure)));
}

/// SignIn or SignUp: the email and password (and a name, to sign up) given,
/// or else the submitting form's fields of those names.
void _studioAuthenticate(Storefront storefront, bool signUp, Map<String, dynamic> arguments, Map<String, dynamic> event,
    void Function(String) notice) {
  final session = storefront.session;
  if (session == null) return notice('Connect this app to a store to sign in.');
  final auth = _StudioAuth.of(storefront);
  if (auth.working) return;
  final values = event['values'] is Map ? Map<String, dynamic>.from(event['values'] as Map) : event;
  String given(String key) => studioText(arguments[key] ?? values[key]).trim();
  final email = given('email');
  final password = studioText(arguments['password'] ?? values['password']);
  if (!email.contains('@')) return auth.set(storefront, false, 'Enter your email address.');
  if (password.isEmpty) return auth.set(storefront, false, 'Enter your password.');
  if (signUp && password.length < 8) return auth.set(storefront, false, 'Choose a password of 8 characters or more.');
  auth.set(storefront, true, null);
  final name = given('name');
  (signUp ? session.signUp(email, password, displayName: name.isEmpty ? null : name) : session.signIn(email, password)).then(
      (_) {
        auth.set(storefront, false, null);
        // Their orders, now the account's.
        storefront.loadOrders().ignore();
      },
      onError: (Object failure) => auth.set(storefront, false, studioErrorText(failure)));
}

/// The storefront's bindings, worked out once rather than on every read.
///
/// Storefront.bindings() turns every store, product, category, cart line
/// and order into a map, and every expression on a page reads through it,
/// so a 74-product menu rebuilt it for each product: thousands of maps per
/// build. Kept until the storefront changes (it notifies) or the next frame.
class _StudioBindingsCache {
  _StudioBindingsCache(this.storefront) {
    storefront.addListener(_results.clear);
  }
  static final _caches = Expando<_StudioBindingsCache>();
  static _StudioBindingsCache of(Storefront storefront) {
    if (!_counting) {
      _counting = true;
      WidgetsBinding.instance.addPersistentFrameCallback((_) => _frames++);
    }
    return _caches[storefront] ??= _StudioBindingsCache(storefront);
  }
  /// Frames drawn: an app can change a storefront field without notifying,
  /// so nothing is kept past the frame it was worked out in.
  static int _frames = 0;
  static bool _counting = false;

  final Storefront storefront;
  /// By the product whose options they include (the open product), by identity.
  final _results = Map<Object?, Map<String, dynamic>>.identity();
  int? _frame;

  Map<String, dynamic> bindings(dynamic product) {
    final frame = _frames;
    if (frame != _frame || _results.length > 256) {
      _frame = frame;
      _results.clear();
    }
    return _results[product] ??= storefront.bindings(product: product);
  }
}

/// A list item built once it scrolls near the screen.
///
/// A ForEach over the storefront's stores, menu or orders builds every item
/// up front otherwise: a 74-product menu evaluated and laid out 74 cards
/// (and started 74 pictures) before its first frame. The first few are built
/// at once, so the top of the page never waits; the rest hold a space about
/// their size until the page scrolls within a screen of them.
class StudioLazyItem extends StatefulWidget {
  const StudioLazyItem({super.key, required this.index, required this.builder});
  final int index;
  final WidgetBuilder builder;
  /// Built straight away: about a screenful in a grid or list.
  static const eager = 6;
  @override
  State<StudioLazyItem> createState() => _StudioLazyItemState();
}

class _StudioLazyItemState extends State<StudioLazyItem> {
  late bool _built = widget.index < StudioLazyItem.eager;
  ScrollPosition? _position;

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (_built) return;
    final position = Scrollable.maybeOf(context)?.position;
    // Not in a scroll view: nothing to wait for.
    if (position == null) {
      _built = true;
      return;
    }
    if (position != _position) {
      _position?.removeListener(_check);
      _position = position..addListener(_check);
    }
    WidgetsBinding.instance.addPostFrameCallback((_) => _check());
  }

  void _check() {
    if (_built || !mounted) return;
    final box = context.findRenderObject();
    final view = Scrollable.maybeOf(context)?.context.findRenderObject();
    if (box is! RenderBox || view is! RenderBox || !box.attached || !box.hasSize || !view.hasSize) return;
    final item = MatrixUtils.transformRect(box.getTransformTo(view), Offset.zero & box.size);
    // Within a screen of what shows, either way.
    final near = (Offset.zero & view.size).inflate(math.max(view.size.width, view.size.height));
    if (!item.overlaps(near)) return;
    _position?.removeListener(_check);
    _position = null;
    setState(() => _built = true);
  }

  @override
  void dispose() {
    _position?.removeListener(_check);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (_built) return widget.builder(context);
    // About an item's size: a grid cell's card, or a list row.
    return LayoutBuilder(builder: (context, constraints) {
      final width = constraints.hasBoundedWidth ? constraints.maxWidth : 160.0;
      return SizedBox(width: width, height: width < 320 ? width * 1.4 : 96);
    });
  }
}
class StudioValue {
  const StudioValue(this.name, this.arguments);
  final String name;
  final Map<String, dynamic> arguments;
}
String studioRoute(dynamic route) {
  if (route is StudioValue) {
    // The project's own page for the record (/stores/$storeId/products/$productId …),
    // its id in the record's param; another param is filled as it navigates.
    final id = Uri.encodeComponent(studioText(route.arguments['id']));
    final record = const {
      'Route.product': ['product', 'productId', r'/product/$productId'],
      'Route.category': ['category', 'categoryId', r'/category/$categoryId'],
    }[route.name] ?? const ['tracking', 'orderId', r'/orders/$orderId'];
    final pattern = studioRoutePaths[record[0]] ?? record[2];
    return pattern.split('/').map((part) => part == r'$' + record[1] ? id : part).join('/');
  }
  final registered = route is String ? studioRoutePaths[route] : null;
  if (registered != null) return registered;
  return const {'home': '/', 'menu': '/', 'cart': '/cart', 'checkout': '/checkout',
    'orders': '/orders', 'account': '/account', 'addresses': '/addresses',
    'resetPassword': '/reset-password', 'tracking': r'/orders/$orderId',
    'location': '/select-location', 'stores': '/select-store'}[route] ?? studioText(route);
}

dynamic studioFunction(BuildContext context, Map<String, dynamic> bindings, String name, List<dynamic> args) {
  final a = args.isNotEmpty ? args[0] : null;
  final b = args.length > 1 ? args[1] : null;
  final c = args.length > 2 ? args[2] : null;
  num number(dynamic value) => value is num ? value : 0;
  String text(dynamic value) => studioText(value);
  switch (name) {
    case 'currentRoute': return ModalRoute.of(context)?.settings.name ?? '/';
    case 'isDarkMode': return Theme.of(context).brightness == Brightness.dark;
    case 'isCurrentRoute':
      final target = studioRoute(a);
      final pattern = target.split('/').map((part) => part.startsWith(r'$') ? '[^/]+' : RegExp.escape(part)).join('/');
      return RegExp('^' + pattern + r'$').hasMatch(ModalRoute.of(context)?.settings.name ?? '/');
    case 'upper': return a == null ? null : text(a).toUpperCase();
    case 'lower': return a == null ? null : text(a).toLowerCase();
    case 'truncate': return a == null ? null : text(a).substring(0, number(b).toInt().clamp(0, text(a).length));
    case 'length': case 'count': return a is String ? a.length : a is List ? a.length : 0;
    case 'join': return a is List ? a.map((value) => value is Map || value is List ? '' : text(value)).join(text(b)) : '';
    case 'contains': return a is String ? a.contains(text(b)) : a is List && a.contains(b);
    case 'isEmpty': return a == null || a == '' || a is List && a.isEmpty;
    case 'min': return math.min(number(a), number(b));
    case 'max': return math.max(number(a), number(b));
    case 'round': return (number(a) + 0.5).floor();
    case 'floor': return number(a).floor();
    case 'ceil': return number(a).ceil();
    case 'clamp': return number(a).clamp(number(b), number(c));
    case 'take': return a is List ? a.take(number(b).toInt().clamp(0, a.length)).toList() : [];
    case 'first': return a is List && a.isNotEmpty ? a.first : null;
    case 'ratio':
      final parts = text(a).split(':').map((part) => num.tryParse(part)).toList();
      return parts.length == 2 && parts[0] != null && parts[1] != null && parts[0]! > 0 && parts[1]! > 0 ? parts[0]! / parts[1]! : 1;
    case 'discountPercent': return number(b) > number(a) && number(b) > 0 ? ((1 - number(a) / number(b)) * 100 + 0.5).floor().clamp(0, 100) : 0;
    case 'formatMoney':
      final format = bindings['_formatMoney'];
      if (format is String Function(num)) return format(number(a));
      // The page's store's currency, else the store the customer chose: never one neither uses.
      final currency = studioRead(bindings, ['store', 'currency']) ?? Storefront.instance.store?.json['currency'] ?? 'ZAR';
      return '$currency ' + (number(a) / 100).toStringAsFixed(2);
    case 'filter':
      return a is List ? a.where((item) => studioRead(item, text(b).split('.')) == c).take(200).toList() : [];
    case 'search':
      if (a is! List) return [];
      final words = text(b).toLowerCase().trim().split(RegExp(r'\s+')).where((word) => word.isNotEmpty);
      final fields = c is List ? c : <dynamic>[];
      return a.where((item) {
        final haystack = fields.map((field) => studioRead(item, text(field).split('.'))).map((value) => value is List ? value.join(' ') : text(value)).join(' ').toLowerCase();
        return words.every(haystack.contains);
      }).take(200).toList();
  }
  throw UnsupportedError('Unknown CDSL function: $name');
}

String studioText(dynamic value) => value?.toString() ?? '';
/// Like the Studio preview: anything that isn't a number counts as 0, so a
/// CDSL shorthand such as "isDesktop() && Space.lg" (false on a phone)
/// means "none" instead of crashing.
double studioNumber(dynamic value) => value is num ? value.toDouble() : 0;
int studioInt(dynamic value) => studioNumber(value).toInt();
Color studioPaint(dynamic value) {
  if (value is Color) return value;
  if (value is String && RegExp(r'^#[0-9a-fA-F]{6}$').hasMatch(value)) {
    return Color(0xff000000 | int.parse(value.substring(1), radix: 16));
  }
  throw ArgumentError('Expected a Color or a six-digit hex color.');
}
bool studioTruthy(dynamic value) => value != null && value != false && value != '' && value != 0;
/// Shadow tokens (Shadow.sm/md/lg; none or anything else is no shadow), at
/// the depths the Studio preview draws: [y offset, blur].
const _studioShadowDepths = {'sm': [1.0, 3.0], 'md': [4.0, 14.0], 'lg': [10.0, 30.0]};
List<BoxShadow> studioBoxShadow(dynamic value) {
  final depth = _studioShadowDepths[value];
  if (depth == null) return const [];
  return [BoxShadow(color: const Color(0x24000000), offset: Offset(0, depth[0]), blurRadius: depth[1])];
}
List<Shadow> studioTextShadows(dynamic value) {
  final depth = _studioShadowDepths[value];
  if (depth == null) return const [];
  return [Shadow(color: const Color(0x40000000), offset: Offset(0, depth[0] / 2), blurRadius: depth[1] / 2)];
}

dynamic studioRead(dynamic value, List<dynamic> path) {
  for (final key in path) {
    if (const ['__proto__', 'constructor', 'prototype'].contains(key)) return null;
    if (value is Map) {
      value = value[key];
    } else if (value is List && key is num && key == key.toInt() && key >= 0 && key < value.length) {
      value = value[key.toInt()];
    } else if (key == 'length' && (value is List || value is String)) {
      // cart.length, like the preview.
      value = value is List ? value.length : (value as String).length;
    } else {
      return null;
    }
  }
  return value;
}

dynamic studioBinary(String op, dynamic left, dynamic Function() right) {
  if (op == '&&') return studioTruthy(left) ? right() : left;
  if (op == '||') return studioTruthy(left) ? left : right();
  if (op == '??') return left ?? right();
  final value = right();
  if (op == '==') return left == value;
  if (op == '!=') return left != value;
  if (left is String && value is String) {
    if (op == '+') return left + value;
    final comparison = left.compareTo(value);
    if (op == '<') return comparison < 0;
    if (op == '>') return comparison > 0;
    if (op == '<=') return comparison <= 0;
    if (op == '>=') return comparison >= 0;
  }
  if (left is! num || value is! num) return null;
  switch (op) {
    case '+': return left + value;
    case '-': return left - value;
    case '*': return left * value;
    case '/': return value == 0 ? null : left / value;
    case '%': return value == 0 ? null : left.remainder(value);
    case '<': return left < value;
    case '>': return left > value;
    case '<=': return left <= value;
    case '>=': return left >= value;
  }
  throw ArgumentError('Unsupported operator: $op');
}

/// Padding from a number or insets; anything else (false, null) is none.
EdgeInsetsGeometry studioInsets(dynamic value) => value is EdgeInsetsGeometry
    ? value : value is num ? EdgeInsets.all(value.toDouble()) : EdgeInsets.zero;

List<Widget> studioGaps(List<Widget> children, double gap, Axis axis) {
  if (gap == 0 || children.length < 2) return children;
  return [for (var i = 0; i < children.length; i++) ...[
    if (i > 0) SizedBox(width: axis == Axis.horizontal ? gap : 0, height: axis == Axis.vertical ? gap : 0),
    children[i],
  ]];
}

List<dynamic> studioItems(dynamic value, dynamic limit) => value is List
    ? value.take(studioInt(limit).clamp(0, 100)).toList() : [];

/// The Studio preview's own palette (its light fixture theme). Project Config
/// overrides arrive through [StudioColors] on the app's ThemeData, so a
/// downloaded app paints exactly the colours the preview showed.
const studioDefaultColors = <String, Color>{
  'primary': Color(0xff00d2a6),
  'primaryInk': Color(0xff0f1115),
  'background': Color(0xfff8f9fa),
  'surface': Color(0xffffffff),
  'surfaceAlt': Color(0xfff8f9fa),
  'text': Color(0xff2b2d31),
  'textMuted': Color(0xff5c6068),
  'border': Color(0xffe2e8f0),
  'success': Color(0xff00d2a6),
  'danger': Color(0xffe5484d),
  'warning': Color(0xffe8a33d),
};

/// The preview's dark fixture theme: the defaults a dark theme starts from.
const studioDarkDefaultColors = <String, Color>{
  'primary': Color(0xff00d2a6),
  'primaryInk': Color(0xff0f1115),
  'background': Color(0xff0f1115),
  'surface': Color(0xff171a21),
  'surfaceAlt': Color(0xff0f1115),
  'text': Color(0xffe9ebef),
  'textMuted': Color(0xff9ba1ac),
  'border': Color(0xff262b35),
  'success': Color(0xff00d2a6),
  'danger': Color(0xffff6b70),
  'warning': Color(0xfff5b95c),
};

class StudioColors extends ThemeExtension<StudioColors> {
  const StudioColors(this.colors);
  final Map<String, Color> colors;
  Color? operator [](String name) => colors[name];
  @override
  StudioColors copyWith({Map<String, Color>? colors}) => StudioColors(colors ?? this.colors);
  @override
  StudioColors lerp(StudioColors? other, double t) => t < 0.5 || other == null ? this : other;
}

/// A Material theme built from the Studio palette, so widgets Studio doesn't
/// colour explicitly (buttons, fields, the page background) match too.
/// The preview's type: Plus Jakarta Sans, with CSS's line-height 1.5 (extra
/// leading split evenly above and below, as browsers do).
TextStyle studioFont({double? fontSize, FontWeight? fontWeight, Color? color}) => GoogleFonts.plusJakartaSans(
  textStyle: TextStyle(fontSize: fontSize, fontWeight: fontWeight, color: color,
      height: 1.5, leadingDistribution: TextLeadingDistribution.even),
);

/// [fontSize] is FontSize.md, the size of a Text without one; [buttonFontSize]
/// a button label's (Config's FontSize.md when set, 14px otherwise).
/// [brightness] picks the defaults the overrides go over: the light or the
/// dark fixture palette.
ThemeData studioTheme(Map<String, Color> overrides,
    {double buttonRadius = 6, double fontSize = 16, double buttonFontSize = 14,
    Brightness brightness = Brightness.light}) {
  final c = {...(brightness == Brightness.dark ? studioDarkDefaultColors : studioDefaultColors), ...overrides};
  final scheme = ColorScheme.fromSeed(seedColor: c['primary']!, brightness: brightness).copyWith(
    primary: c['primary'], onPrimary: c['primaryInk'],
    surface: c['surface'], onSurface: c['text'], onSurfaceVariant: c['textMuted'],
    surfaceContainerHighest: c['surfaceAlt'], outline: c['border'], error: c['danger'],
  );
  final base = ThemeData(useMaterial3: true, colorScheme: scheme).textTheme;
  final body = studioFont(fontSize: fontSize);
  return ThemeData(
    useMaterial3: true,
    colorScheme: scheme,
    scaffoldBackgroundColor: c['background'],
    canvasColor: c['background'],
    textTheme: GoogleFonts.plusJakartaSansTextTheme(base).copyWith(
      bodyLarge: base.bodyLarge?.merge(body),
      bodyMedium: base.bodyMedium?.merge(body),
    ),
    // Sizes as authored, like the browser: no 48px touch-target padding.
    materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
    visualDensity: VisualDensity.standard,
    extensions: [StudioColors(c)],
    filledButtonTheme: FilledButtonThemeData(style: _studioButton(buttonRadius, buttonFontSize)),
    outlinedButtonTheme: OutlinedButtonThemeData(style: _studioButton(buttonRadius, buttonFontSize)),
    textButtonTheme: TextButtonThemeData(style: _studioButton(buttonRadius, buttonFontSize)),
    elevatedButtonTheme: ElevatedButtonThemeData(style: _studioButton(buttonRadius, buttonFontSize)),
  );
}
/// The preview's button: 10px x 14px padding inside a 1px border (so 11 x 15
/// here, where the border is drawn over the padding), semibold label.
ButtonStyle _studioButton(double radius, double fontSize) => ButtonStyle(
  shape: WidgetStatePropertyAll(RoundedRectangleBorder(borderRadius: BorderRadius.circular(radius))),
  padding: const WidgetStatePropertyAll(EdgeInsets.symmetric(horizontal: 15, vertical: 11)),
  minimumSize: const WidgetStatePropertyAll(Size(0, 32)),
  tapTargetSize: MaterialTapTargetSize.shrinkWrap,
  visualDensity: VisualDensity.standard,
  textStyle: WidgetStatePropertyAll(studioFont(fontSize: fontSize, fontWeight: FontWeight.w600)),
);

Color studioColor(BuildContext context, String name) =>
    Theme.of(context).extension<StudioColors>()?[name] ??
    studioDefaultColors[name] ??
    (throw ArgumentError('Unknown color: ' + name));

/// Each page's path by page id, registered by main.dart so Route tokens go to
/// this project's own pages.
final Map<String, String> studioRoutePaths = {};

/// How the messages actions show look: Config's notice, set by main.dart.
class StudioNoticeStyle {
  const StudioNoticeStyle({this.background, this.color, this.top = false, this.seconds = 4});
  /// Colour tokens; null is the theme's own snack bar colours.
  final String? background, color;
  /// At the top of the screen, not the bottom.
  final bool top;
  final num seconds;
}

StudioNoticeStyle studioNotice = const StudioNoticeStyle();

/// A message an action shows (ShowMessage, a failure), as Config's notice says.
SnackBar studioSnackBar(BuildContext context, String message) {
  final style = studioNotice;
  final color = style.color == null ? null : studioColor(context, style.color!);
  return SnackBar(
    content: Text(message, style: color == null ? null : TextStyle(color: color)),
    backgroundColor: style.background == null ? null : studioColor(context, style.background!),
    duration: Duration(milliseconds: (style.seconds * 1000).round()),
    behavior: style.top ? SnackBarBehavior.floating : null,
    // At the top: floating, its margin keeping it under the status bar.
    margin: style.top
        ? EdgeInsets.only(left: 16, right: 16, bottom: math.max(16.0, MediaQuery.sizeOf(context).height - MediaQuery.paddingOf(context).top - 96))
        : null,
  );
}

/// The light or dark mode ToggleDarkMode switched the app to; null follows
/// Config's theme mode. main.dart listens to it.
final ValueNotifier<ThemeMode?> studioThemeMode = ValueNotifier<ThemeMode?>(null);

/// Navigate like the preview: when one tap runs several navigations (a tap
/// that bubbles through nested tappable boxes), the last one wins.
bool _studioNavigating = false;
void studioNavigate(BuildContext context, dynamic route, [Map<String, dynamic>? values]) {
  final navigator = Navigator.of(context);
  // A page path's $params filled from the values given and the store chosen,
  // so the menu at /stores/$storeId opens on that store, not on the pattern.
  final store = Storefront.instance.store?.json;
  final name = studioRoute(route).split('/').map((part) {
    if (!part.startsWith(r'$')) return part;
    final key = part.substring(1);
    final value = values?[key] ?? (key == 'storeId' ? (store?['id'] ?? store?['slug']) : null);
    return value == null || studioText(value).isEmpty ? part : Uri.encodeComponent(studioText(value));
  }).join('/');
  // Going somewhere from an open drawer or dialog closes it first.
  navigator.popUntil((open) => open is! PopupRoute);
  if (_studioNavigating) {
    navigator.pushReplacementNamed(name, arguments: values);
  } else {
    navigator.pushNamed(name, arguments: values);
  }
  _studioNavigating = true;
  Future.microtask(() => _studioNavigating = false);
}

/// Animate: its child animates in once, when it first appears, as the
/// preview's CSS does — fade, slide in from a side by [distance] pixels, scale
/// or pop — over [duration] ms after [delay] ms, along [curve]. Shown at once
/// where the platform asks for less motion.
class StudioAnimate extends StatefulWidget {
  const StudioAnimate({
    super.key,
    required this.child,
    this.effect = 'fade',
    this.duration = 400,
    this.delay = 0,
    this.curve = Curves.easeOut,
    this.distance = 24,
  });
  final Widget child;
  final Object? effect;
  final Object? duration;
  final Object? delay;
  final Curve curve;
  final Object? distance;

  @override
  State<StudioAnimate> createState() => _StudioAnimateState();
}

class _StudioAnimateState extends State<StudioAnimate> with SingleTickerProviderStateMixin {
  late final AnimationController _controller = AnimationController(vsync: this, duration: _duration);
  Timer? _start;

  Duration get _duration => Duration(milliseconds: studioNumber(widget.duration).round().clamp(0, 10000));

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (_controller.isAnimating || _controller.value > 0 || _start != null) return;
    _begin();
  }

  /// An entrance plays once per widget, but a changed effect, duration,
  /// delay, curve or distance plays it again, as the preview does — else an
  /// edit to an Animate that has already played shows nothing.
  @override
  void didUpdateWidget(StudioAnimate old) {
    super.didUpdateWidget(old);
    if (old.effect == widget.effect && old.duration == widget.duration && old.delay == widget.delay &&
        old.curve == widget.curve && old.distance == widget.distance) return;
    _controller.duration = _duration;
    _replay();
  }

  /// Hot reload keeps state, so a finished entrance would never show again
  /// while editing (Studio's desktop Run follows the editor with hot reload).
  @override
  void reassemble() {
    super.reassemble();
    _replay();
  }

  void _replay() {
    _start?.cancel();
    _start = null;
    _controller.value = 0;
    _begin();
  }

  void _begin() {
    // Accessibility (or a 0 transition animation scale on Android): no motion.
    if (MediaQuery.maybeDisableAnimationsOf(context) ?? false) {
      _controller.value = 1;
      return;
    }
    final delay = studioNumber(widget.delay).round().clamp(0, 10000);
    if (delay == 0) {
      _controller.forward();
    } else {
      _start = Timer(Duration(milliseconds: delay), () {
        _start = null;
        if (mounted) _controller.forward();
      });
    }
  }

  @override
  void dispose() {
    _start?.cancel();
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _controller,
      child: widget.child,
      builder: (context, child) {
        final t = widget.curve.transform(_controller.value);
        final away = (1 - t) * studioNumber(widget.distance);
        final Widget moved;
        switch (widget.effect) {
          case 'slideUp':
            moved = Transform.translate(offset: Offset(0, away), child: child);
          case 'slideDown':
            moved = Transform.translate(offset: Offset(0, -away), child: child);
          case 'slideLeft':
            moved = Transform.translate(offset: Offset(away, 0), child: child);
          case 'slideRight':
            moved = Transform.translate(offset: Offset(-away, 0), child: child);
          case 'scale':
            moved = Transform.scale(scale: 0.9 + 0.1 * t, child: child);
          case 'pop':
            moved = Transform.scale(scale: 0.6 + 0.4 * t, child: child);
          default:
            moved = child!;
        }
        return Opacity(opacity: t.clamp(0.0, 1.0), child: moved);
      },
    );
  }
}

/// A tappable box. Taps bubble to enclosing boxes like a click in the
/// preview (inner handler first), and when [fill] is set it takes the full
/// width it's given — a block with width: 100% — sharing a row with others.
class StudioTap extends StatelessWidget implements StudioFill, StudioCapped {
  const StudioTap({super.key, required this.onTap, required this.child, this.fill = false, this.label, this.maxWidth});
  @override
  final double? maxWidth;
  final VoidCallback onTap;
  final Widget child;
  @override
  final bool fill;
  final String? label;
  @override
  Widget build(BuildContext context) {
    final outer = context.dependOnInheritedWidgetOfExactType<_StudioTapScope>()?.onTap;
    void tap() {
      onTap();
      outer?.call();
    }
    Widget body = GestureDetector(behavior: HitTestBehavior.opaque, onTap: tap, child: child);
    if (label != null) body = Semantics(label: label, button: true, child: body);
    body = _StudioTapScope(onTap: tap, child: body);
    if (!fill) return body;
    return LayoutBuilder(builder: (context, constraints) =>
        constraints.hasBoundedWidth ? SizedBox(width: maxWidth ?? double.infinity, child: body) : body);
  }
}
class _StudioTapScope extends InheritedWidget {
  const _StudioTapScope({required this.onTap, required super.child});
  final VoidCallback onTap;
  @override
  bool updateShouldNotify(_StudioTapScope oldWidget) => false;
}

/// Widgets that, like a CSS block with width: 100%, take all the width they
/// are given. In a row, StudioFlex shares the width between them.
abstract class StudioFill {
  bool get fill;
}

/// A full-width block with a CSS max-width: in a row it takes its cap
/// instead of an equal share.
abstract class StudioCapped {
  double? get maxWidth;
}

/// A Box with an explicit width and/or height. Like CSS, a flex container's
/// stretch never overrides those; StudioFlex aligns it to the start instead.
class StudioSized extends StatelessWidget {
  const StudioSized({super.key, this.width = false, this.height = false, required this.child});
  final bool width, height;
  final Widget child;
  @override
  Widget build(BuildContext context) => child;
}

/// AspectRatio that also works where nothing bounds it (e.g. a Positioned with
/// only right/bottom): there, like CSS, the content decides its own size.
class StudioAspectRatio extends StatelessWidget {
  const StudioAspectRatio({super.key, required this.aspectRatio, required this.child});
  final double aspectRatio;
  final Widget child;
  @override
  Widget build(BuildContext context) => LayoutBuilder(
    builder: (context, constraints) {
      final sized = AspectRatio(aspectRatio: aspectRatio, child: child);
      return constraints.hasBoundedWidth || constraints.hasBoundedHeight
          ? sized
          : child;
    },
  );
}

/// TextField / SearchField with every appearance option the Studio preview
/// supports. Where nothing bounds its width (e.g. inside a Row) it takes a
/// browser input's default width instead of failing layout.
class StudioTextInput extends StatefulWidget {
  const StudioTextInput({super.key, this.value, this.controlled = false,
    this.label, this.hint, this.helper, this.enabled = true,
    this.onChanged, this.onSubmitted, this.name = '',
    this.type = 'text', this.search = false, this.clearable = false,
    this.rows, this.maxLength, this.semanticLabel,
    this.background, this.color, this.border, this.radius, this.padding,
    this.fontSize, this.labelColor, this.helperColor, this.placeholderColor,
    this.focusColor, this.required = false, this.min, this.max, this.minLength});
  final dynamic value;
  final bool controlled;
  final String? label, hint, helper, semanticLabel;
  final bool enabled, search, clearable, required;
  final String name, type;
  final int? rows, maxLength, minLength;
  final num? min, max;
  final StudioAction? onChanged, onSubmitted;
  final Color? background, color, labelColor, helperColor, placeholderColor, focusColor;
  final BoxBorder? border;
  final double? radius, fontSize;
  final EdgeInsetsGeometry? padding;
  @override
  State<StudioTextInput> createState() => _StudioTextInputState();
}

class _StudioTextInputState extends State<StudioTextInput> implements StudioFormField {
  late final controller = TextEditingController(text: studioText(widget.value));
  /// What it started with, for a reset.
  late final String initial = studioText(widget.value);
  StudioFormState? form;
  String? error;

  /// Checked with the preview's rules when its form is submitted.
  @override
  String? validate() {
    final label = widget.label?.isNotEmpty == true
        ? widget.label!
        : widget.semanticLabel?.isNotEmpty == true
            ? widget.semanticLabel!
            : widget.name.isNotEmpty
                ? widget.name
                : 'This field';
    final message = widget.enabled
        ? studioValidate(event(controller.text)['input']['value'], label: label, type: widget.type,
            required: widget.required, min: widget.min, max: widget.max,
            minLength: widget.minLength, maxLength: widget.maxLength)
        : null;
    if (message != error) setState(() => error = message);
    return message;
  }

  @override
  void reset() {
    controller.text = initial;
    setState(() => error = null);
    report(initial);
  }
  @override
  void didUpdateWidget(covariant StudioTextInput oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.controlled && controller.text != studioText(widget.value)) {
      controller.value = TextEditingValue(text: studioText(widget.value),
        selection: TextSelection.collapsed(offset: studioText(widget.value).length));
    }
  }
  /// Like the preview: a number field reports a number, or null when empty.
  Map<String, dynamic> event(String value) => {'input': {
    'value': widget.type == 'number' ? num.tryParse(value) : value,
    'name': widget.name,
  }};
  /// Tells the form around it (if any) this field's value, under its name.
  void report(String value) {
    if (widget.name.isNotEmpty) StudioForm.of(context)?.values[widget.name] = event(value)['input']['value'];
  }
  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    // One of its form's fields, checked and reset with it.
    final around = StudioForm.of(context);
    if (around != form) {
      form?.fields.remove(this);
      form = around;
      around?.fields.add(this);
    }
    report(controller.text);
  }
  void changed(String value) {
    if (widget.clearable || widget.search) setState(() {});
    report(value);
    // An error shown is rechecked as they type, and goes once it's fixed.
    if (error != null) validate();
    widget.onChanged?.call(event(value));
  }
  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final given = widget.border;
    // The preview's field: 13px text, 11px x 12px padding, a 9px radius, a 1px
    // border and the surface fill, unless the source sets its own.
    final side = given is Border ? given.top : BorderSide(color: studioColor(context, 'border'));
    final fontSize = widget.fontSize ?? 13;
    OutlineInputBorder outline(BorderSide s) => OutlineInputBorder(
      borderRadius: BorderRadius.circular(widget.radius ?? 9), borderSide: s);
    final clear = (widget.clearable || widget.search) && controller.text.isNotEmpty && widget.enabled
        ? IconButton(
            tooltip: 'Clear',
            icon: const Icon(Icons.close),
            onPressed: () { controller.clear(); changed(''); })
        : null;
    final multiline = (widget.rows ?? 1) > 1 && widget.type != 'password';
    final field = TextField(
      controller: controller,
      enabled: widget.enabled,
      obscureText: widget.type == 'password',
      keyboardType: const {
        'email': TextInputType.emailAddress, 'number': TextInputType.numberWithOptions(decimal: true),
        'tel': TextInputType.phone, 'url': TextInputType.url,
      }[widget.type] ?? (multiline ? TextInputType.multiline : TextInputType.text),
      textInputAction: widget.search ? TextInputAction.search : null,
      minLines: multiline ? widget.rows : null,
      maxLines: multiline ? widget.rows : 1,
      maxLength: widget.maxLength,
      style: studioFont(fontSize: fontSize, color: widget.color ?? studioColor(context, 'text')),
      decoration: InputDecoration(
        hintText: widget.hint,
        hintStyle: studioFont(fontSize: fontSize, color: widget.placeholderColor ?? studioColor(context, 'textMuted')),
        filled: true,
        fillColor: widget.background ?? studioColor(context, 'surface'),
        contentPadding: widget.padding ?? const EdgeInsets.symmetric(horizontal: 12, vertical: 11),
        isDense: true,
        counterText: '',
        errorText: error,
        errorStyle: studioFont(fontSize: 11, color: studioColor(context, 'danger')),
        prefixIcon: widget.search ? const Icon(Icons.search) : null,
        suffixIcon: clear,
        border: outline(side),
        enabledBorder: outline(side),
        disabledBorder: outline(side),
        focusedBorder: outline(side.copyWith(
          color: widget.focusColor ?? theme.colorScheme.primary,
          width: side.width < 1.5 ? 1.5 : side.width)),
      ),
      onChanged: changed,
      onSubmitted: (value) => widget.onSubmitted?.call(event(value)),
    );
    final label = widget.label != null && widget.label!.isNotEmpty ? widget.label : null;
    final semantics = widget.semanticLabel ?? label;
    final input = semantics == null
        ? field : Semantics(label: semantics, textField: true, child: field);
    // Like the preview: the label above the field and helper text below it,
    // 6px apart.
    final labelled = label == null && widget.helper == null
        ? input
        : Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            mainAxisSize: MainAxisSize.min,
            children: [
              if (label != null)
                ExcludeSemantics(
                  child: Text(label, style: studioFont(fontSize: fontSize, fontWeight: FontWeight.w500,
                      color: widget.labelColor ?? studioColor(context, 'text'))),
                ),
              if (label != null) const SizedBox(height: 6),
              input,
              if (widget.helper != null) const SizedBox(height: 6),
              if (widget.helper != null)
                Text(widget.helper!, style: studioFont(fontSize: 11,
                    color: widget.helperColor ?? studioColor(context, 'textMuted'))),
            ],
          );
    return LayoutBuilder(
      builder: (context, constraints) => constraints.hasBoundedWidth
          ? labelled : SizedBox(width: 240, child: labelled),
    );
  }
  @override
  void dispose() { form?.fields.remove(this); controller.dispose(); super.dispose(); }
}

/// Row / Column / Flex with the preview's CSS behaviour: stretch and "fill the
/// main axis" only where that axis is bounded (CSS falls back to content size,
/// Flutter would throw), and Expanded/Flexible children behave as plain
/// content when there is no space to share.
class StudioFlex extends StatelessWidget implements StudioFill {
  const StudioFlex({super.key, required this.direction, this.fillWidth = false,
    this.mainAxisAlignment = MainAxisAlignment.start,
    this.crossAxisAlignment = CrossAxisAlignment.start,
    this.mainAxisSize = MainAxisSize.min, this.children = const <Widget>[]});
  final Axis direction;
  final MainAxisAlignment mainAxisAlignment;
  final CrossAxisAlignment crossAxisAlignment;
  final MainAxisSize mainAxisSize;
  final List<Widget> children;
  /// CSS width: 100% (a Flex that fills its main axis): it fills a column and
  /// shares a row with the other full-width items.
  final bool fillWidth;
  @override
  bool get fill => fillWidth;
  @override
  Widget build(BuildContext context) => LayoutBuilder(
    builder: (context, constraints) {
      final horizontal = direction == Axis.horizontal;
      final stretch = crossAxisAlignment == CrossAxisAlignment.stretch;
      Widget sized(Widget child) =>
          stretch && child is StudioSized && (horizontal ? child.height : child.width)
              ? Align(alignment: AlignmentDirectional.topStart, child: child)
              : child;
      // Like a CSS flex item, text shrinks (and wraps) to the room its
      // siblings leave instead of pushing the row past its edge — but only
      // shrinks: where something else grows into the free space, text keeps
      // its own width.
      final grows = children.any((child) =>
          child is Flexible || child is Spacer || (child is StudioFill && (child as StudioFill).fill));
      Widget shared(Widget child) {
        if (horizontal && !grows && child is Text) return Flexible(child: child);
        if (!(horizontal && child is StudioFill && (child as StudioFill).fill)) return sized(child);
        final cap = child is StudioCapped ? (child as StudioCapped).maxWidth : null;
        return cap != null ? SizedBox(width: cap, child: child) : Expanded(child: child);
      }
      final mainBounded = horizontal ? constraints.hasBoundedWidth : constraints.hasBoundedHeight;
      final crossBounded = horizontal ? constraints.hasBoundedHeight : constraints.hasBoundedWidth;
      return Flex(
        direction: direction,
        mainAxisAlignment: mainAxisAlignment,
        crossAxisAlignment: crossAxisAlignment == CrossAxisAlignment.stretch && !crossBounded
            ? CrossAxisAlignment.start : crossAxisAlignment,
        mainAxisSize: mainBounded ? mainAxisSize : MainAxisSize.min,
        children: mainBounded
            ? [for (final child in children) shared(child)]
            : [for (final child in children) child is Flexible ? child.child : child is Spacer ? const SizedBox.shrink() : sized(child)],
      );
    },
  );
}
/// The tenant API, for a page's imports from it (set by main.dart).
String studioApiUrl = '';

/// The cart and choices the checkout's last quote was asked for.
String _studioQuotedFor = '';

/// The quote kept current while a page shows the checkout: asked for again
/// (after this frame) whenever the cart or a checkout choice changes, so a
/// store's charges show before the order is placed, never after.
void _studioKeepQuote(BuildContext context) {
  final storefront = context.dependOnInheritedWidgetOfExactType<StudioStorefrontScope>()?.notifier ?? Storefront.instance;
  final storeId = storefront.cart.storeId ?? storefront.store?.id;
  if (!storefront.connected || storeId == null || storefront.cart.isEmpty) return;
  if (storefront.checkout.delivery) storefront.checkout.useLocation(storefront.location);
  final key = jsonEncode(storefront.checkout.quoteBody(storeId, storefront.cart.orderItems()));
  if (key == _studioQuotedFor) return;
  _studioQuotedFor = key;
  WidgetsBinding.instance.addPostFrameCallback((_) => unawaited(storefront.refreshQuote()));
}

/// One product, whole (its addon_groups too), from the tenant API.
Future<Map<String, dynamic>?> _studioWholeProduct(dynamic id) async {
  final address = Uri.parse(studioApiUrl.replaceAll(RegExp(r'/+$'), '') + '/api/v1/products/' + Uri.encodeComponent(studioText(id)));
  final response = await http.get(address).timeout(const Duration(seconds: 10));
  if (response.statusCode != 200) throw StateError('product ' + response.statusCode.toString());
  final body = jsonDecode(response.body);
  final data = body is Map && body['data'] is Map ? body['data'] : body;
  return data is Map ? Map<String, dynamic>.from(data) : null;
}

/// The website's address: an import sent with a secret is fetched through
/// its server (GET /studio-data/<page>/<name>), which holds the key.
String studioSiteUrl = '';

/// Where one of an import's parameters comes from (the page's Data settings):
/// route (a path param), query (a query string key), value, import (a path
/// into an earlier import) or store (the app's store).
class StudioImportParam {
  const StudioImportParam(this.name, this.from, [this.value = '', this.fallback]);
  final String name, from, value;
  /// A query param's value when neither the Navigate that opened the page
  /// nor the address says: its search param's default.
  final String? fallback;
}

/// One thing a page imports before it's drawn: from the tenant API (a path,
/// its {params} filled in, and query parameters), an external address, or,
/// sent with a secret, the website's server.
class StudioImport {
  const StudioImport({
    required this.name,
    this.path = '',
    this.query = const [],
    this.url = '',
    this.viaSite = false,
    this.select = '',
    this.params = const [],
    this.auth = false,
    this.client = '',
  });
  final String name, path, url, select;
  /// The customer's own (Client.cart(), …): never fetched, the storefront's
  /// state as it is (studioClient), for an import after it to read.
  final String client;
  final List<String> query;
  final bool viaSite;
  /// The signed-in customer's (their orders, addresses): asked with their
  /// session, and nothing without one.
  final bool auth;
  final List<StudioImportParam> params;

  /// The {params} its address needs: without one it isn't fetched.
  Iterable<String> get required =>
      RegExp(r'\{([A-Za-z_][A-Za-z0-9_-]*)\}').allMatches(path.isNotEmpty ? path : url).map((match) => match[1]!);
}

/// A page's imports, as its CDSL reads them (studioAmbient), by name.
class StudioPageDataScope extends InheritedWidget {
  const StudioPageDataScope({super.key, required this.data, this.loading = false, required super.child});
  final Map<String, dynamic> data;
  /// Still fetching: lists show their loading outline (studioLoading).
  final bool loading;
  @override
  bool updateShouldNotify(StudioPageDataScope oldWidget) => !identical(data, oldWidget.data) || loading != oldWidget.loading;
}

/// A page's imports as bindings: one not fetched (no store chosen yet)
/// leaves the built-in of its name; an imported menu brings its store,
/// categories and the products shown online, as the storefront's own does.
Map<String, dynamic>? studioImported(Map<String, dynamic>? data) {
  if (data == null) return null;
  final out = <String, dynamic>{
    for (final entry in data.entries)
      if (entry.value != null) entry.key: entry.value,
  };
  final menu = out['menu'];
  if (menu is Map && menu['categories'] is List) {
    final categories = menu['categories'] as List;
    out.putIfAbsent('categories', () => categories);
    out.putIfAbsent('category', () => categories.isEmpty ? null : categories.first);
    if (menu['store'] != null) out.putIfAbsent('store', () => menu['store']);
    out.putIfAbsent('products', () => [
          for (final category in categories)
            if (category is Map && category['products'] is List) ...category['products'] as List,
          if (menu['uncategorised'] is List) ...menu['uncategorised'] as List,
        ].where((product) => product is! Map || product['is_available_online'] != false).toList());
  }
  return out;
}

/// Fetches a page's imports when it opens, in order (one may read
/// another's), and hands them to it by name. The page is drawn at once and
/// again as each arrives; one that fails is left out.
class StudioPageData extends StatefulWidget {
  const StudioPageData({super.key, required this.page, required this.imports, required this.child});
  final String page;
  final List<StudioImport> imports;
  final Widget child;

  @override
  State<StudioPageData> createState() => _StudioPageDataState();
}

class _StudioPageDataState extends State<StudioPageData> {
  Map<String, dynamic> data = const {};
  String? loaded;
  bool loading = true;

  /// The app's store: the one it's built for, or the one the customer chose.
  String? get _store {
    final pinned = Storefront.instance.pinnedStoreId;
    return pinned ?? Storefront.instance.store?.id;
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final route = context.dependOnInheritedWidgetOfExactType<StudioScope>()?.values['route'];
    final params = route is Map && route['params'] is Map ? Map<String, dynamic>.from(route['params'] as Map) : <String, dynamic>{};
    // Imports of the app's store are fetched again once the customer chooses one.
    final byStore = widget.imports.any((item) => item.client == 'store' || item.params.any((param) => param.from == 'store'));
    if (byStore) context.dependOnInheritedWidgetOfExactType<StudioStorefrontScope>();
    // The search params the Navigate that opened it gave (its route's arguments).
    final arguments = ModalRoute.of(context)?.settings.arguments;
    _search = arguments is Map ? Map<String, dynamic>.from(arguments) : const {};
    final key = params.toString() + _search.toString() + (byStore ? '@' + (_store ?? '') : '');
    if (key == loaded) return;
    loaded = key;
    _load(params, key);
  }

  Map<String, dynamic> _search = const {};

  Future<void> _load(Map<String, dynamic> routeParams, String key) async {
    if (!loading) setState(() => loading = true);
    var next = <String, dynamic>{};
    for (final item in widget.imports) {
      if (item.client.isNotEmpty) {
        next = {...next, item.name: studioClient(context, const {}, item.client)};
        continue;
      }
      final values = <String, String>{};
      for (final param in item.params) {
        final dynamic value = switch (param.from) {
          'route' => routeParams[param.value],
          'query' => _search[param.value] ?? Uri.base.queryParameters[param.value] ?? param.fallback,
          'import' => studioRead(next, param.value.split('.')),
          'store' => _store,
          _ => param.value,
        };
        if (value != null && studioText(value).isNotEmpty) values[param.name] = studioText(value);
      }
      // Without what it needs (no store chosen yet, say) it isn't asked for.
      if (item.required.any((name) => values[name] == null)) {
        next = {...next, item.name: null};
        continue;
      }
      try {
        next = {...next, item.name: await _fetch(item, values)};
      } catch (_) {
        // Left out: the page shows what it can without it.
      }
      if (!mounted || loaded != key) return;
      setState(() => data = next);
    }
    if (mounted && loaded == key) setState(() => loading = false);
  }

  Future<dynamic> _fetch(StudioImport item, Map<String, String> params) async {
    final used = <String>{};
    String fill(String template) => template.replaceAllMapped(RegExp(r'\{([A-Za-z_][A-Za-z0-9_-]*)\}'), (match) {
          used.add(match[1]!);
          return Uri.encodeComponent(params[match[1]!] ?? '');
        });
    Uri address;
    if (item.viaSite) {
      if (studioSiteUrl.isEmpty) return null;
      address = Uri.parse(studioSiteUrl + '/studio-data/' + Uri.encodeComponent(widget.page) + '/' + Uri.encodeComponent(item.name))
          .replace(queryParameters: params.isEmpty ? null : params);
    } else if (item.path.isNotEmpty) {
      address = Uri.parse(studioApiUrl.replaceAll(RegExp(r'/+$'), '') + '/api/v1' + fill(item.path));
      final query = {for (final name in item.query) if (params[name] != null) name: params[name]!};
      if (query.isNotEmpty) address = address.replace(queryParameters: query);
    } else {
      address = Uri.parse(fill(item.url));
      final rest = {for (final entry in params.entries) if (!used.contains(entry.key)) entry.key: entry.value};
      if (rest.isNotEmpty) address = address.replace(queryParameters: {...address.queryParameters, ...rest});
    }
    final headers = <String, String>{'Accept': 'application/json'};
    if (item.auth) {
      final token = Storefront.instance.session?.token;
      if (token == null || token.isEmpty) return null;
      headers['Authorization'] = 'Bearer ' + token;
    }
    final response = await http.get(address, headers: headers).timeout(const Duration(seconds: 10));
    if (response.statusCode < 200 || response.statusCode >= 300) throw StateError('import failed: ' + response.statusCode.toString());
    final dynamic body = jsonDecode(response.body);
    // The website's server has already picked out the selection.
    return item.viaSite || item.select.isEmpty ? body : studioRead(body, item.select.split('.'));
  }

  @override
  Widget build(BuildContext context) => StudioPageDataScope(data: data, loading: loading, child: widget.child);
}
